    if (type == null) {
        // If the target type is null, return the result object
        @SuppressWarnings("unchecked")
        T temp = (T) result;
        return temp;
    }
    if (result == null) {
        // If the result is null, return null if the target type is not a primitive type
        if (!type.isPrimitive()) {
            return null;
        }
        // For primitive types, return the default value
        if (type == int.class) {
            return type.cast(0);
        }
        if (type == long.class) {
            return type.cast(0L);
        }
        // Handle other primitive types as needed
        throw new ConversionException("Unsupported target type: " + type);
    }
    if (type.isInstance(result)) {
        return type.cast(result);
    }
    throw new ConversionException("Unsupported conversion to target type: " + type);
}

